scripts:
await page.goto('https://katalon-demo-cura.herokuapp.com/');
await cu.click('Make Appointment');
await cu.fill('Username', 'John Doe');
await cu.fill('Password', 'ThisIsNotAPassword');
await cu.click('Login');
await page.evaluate(() => {
  const facility = document.querySelector('#combo_facility');
  facility.value = 'Hongkong CURA Healthcare Center';
  facility.dispatchEvent(new Event('change', {bubbles:true}));
  const readmission = document.querySelector('#chk_hospotal_readmission');
  readmission.checked = true;
  readmission.dispatchEvent(new Event('change', {bubbles:true}));
  const medicaid = document.querySelector('#radio_program_medicaid');
  medicaid.checked = true;
  medicaid.dispatchEvent(new Event('change', {bubbles:true}));
  const date = document.querySelector('#txt_visit_date');
  date.value = '20/05/2030';
  date.dispatchEvent(new Event('input', {bubbles:true}));
  date.dispatchEvent(new Event('change', {bubbles:true}));
  const comment = document.querySelector('#txt_comment');
  comment.value = 'Annual check';
  comment.dispatchEvent(new Event('input', {bubbles:true}));
  comment.dispatchEvent(new Event('change', {bubbles:true}));
});
await cu.click('Book Appointment');
await page.evaluate(() => { const answer = document.body.innerText.match(/Please be informed that your appointment has been booked as following:/)?.[0] || ''; return cu.claim({url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:answer,values:['Hongkong CURA Healthcare Center','Yes','Medicaid','20/05/2030','Annual check'],answer}); });

await page.goto('https://ecommerce-playground.lambdatest.io/index.php?route=product/product&product_id=40');
await cu.click('Add to Cart');
await page.goto('https://ecommerce-playground.lambdatest.io/index.php?route=checkout/checkout');
await cu.click('Guest Checkout');
await cu.click('Continue');
await cu.fill('First Name', 'Alex');
await cu.fill('Last Name', 'Example');
await cu.fill('E-Mail', 'alex@example.com');
await cu.fill('Telephone', '07123456789');
await cu.fill('Address 1', '1 Main Street');
await cu.fill('City', 'Leeds');
await cu.fill('Post Code', 'LS1 1AA');
await cu.getByLabel('Country').selectOption({label:'United Kingdom'});
await cu.getByLabel('Region / State').selectOption({label:'West Yorkshire'});
await cu.click('Continue');
await cu.click('Flat Shipping Rate');
await cu.click('Continue');
await cu.click('Cash On Delivery');
await cu.click('Continue');
await cu.click('I have read and agree to the Terms & Conditions');
await cu.click('Confirm Order');
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Your order has been placed!') ? 'Your order has been placed!' : document.body.innerText.slice(-500), values: [], answer: document.querySelector('h1')?.innerText || ''}))
